for r,c,v in centers:
 g[r][c]=v
 for x,y in [(r-1,c),(r+1,c),(r,c-1),(r,c+1)]: g[x][y]=3; own[(x,y)]=(r,c)
orig=[row[:] for row in g]
# each center rays; scan each cardinal direction, stopping at another cross's 3
hor=[[None]*C for _ in range(R)]; ver=[[None]*C for _ in range(R)]
for r,c,v in centers:
 for dr,dc, arr in [(0,1,hor),(0,-1,hor),(1,0,ver),(-1,0,ver)]:
  i,j=r+dr,c+dc
  while 0<=i<R and 0<=j<C:
   if orig[i][j]==3 and own.get((i,j))!=(r,c): break
   arr[i][j]=v
   i+=dr;j+=dc
out=[row[:] for row in orig]
for i in range(R):
 for j in range(C):
  if orig[i][j]==0:
   if hor[i][j] is not None: out[i][j]=hor[i][j]
   if ver[i][j] is not None: out[i][j]=ver[i][j]
print('\n'.join(' '.join(map(str,row)) for row in out))

